"""Adjusts the web files generated by `flutter create --platforms=web`:
name, colours, iPhone home-screen title, language."""
import json
import pathlib
import re

m = pathlib.Path("web/manifest.json")
d = json.loads(m.read_text(encoding="utf-8"))
d.update({
    "name": "Amane – أمان للأمن الخصوصي",
    "short_name": "Amane",
    "description": "AMANE Sécurité privée : SOS, suivi des agents, espace client.",
    "background_color": "#f7f2e7",
    "theme_color": "#0f2a40",
    "display": "standalone",
    "orientation": "portrait",
    "lang": "ar",
})
m.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")

h = pathlib.Path("web/index.html")
s = h.read_text(encoding="utf-8")
s = s.replace('<html>', '<html lang="ar">', 1)
s = re.sub(r"<title>.*?</title>", "<title>Amane – أمان</title>", s, count=1, flags=re.S)
s = re.sub(r'<meta name="apple-mobile-web-app-title" content="[^"]*">',
           '<meta name="apple-mobile-web-app-title" content="Amane">', s)
s = re.sub(r'<meta name="description" content="[^"]*">',
           '<meta name="description" content="AMANE Sécurité privée – SOS et espace client">', s)
if 'name="theme-color"' not in s:
    s = s.replace("</head>", '  <meta name="theme-color" content="#0f2a40">\n</head>', 1)
h.write_text(s, encoding="utf-8")
print("Web files patched")
